for I in range(1,32):
 d[I]=Int('d%d'%I);s.add(d[I]>=0,d[I]<=15)
for i in range(4):s.add(d[1<<i]==8,d[(1<<i)|16]==7)
s.add(d[16]==14)
for A in range(32):
 for B in range(32):
  if A&B==A:s.add(d[A]>=d[B])
  s.add(d[A]+d[B]<=d[A|B]+d[A&B])
for J in range(1,16):s.add(d[J]-d[J|16]>=0,d[J]-d[J|16]<=1)
